#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace off {
constexpr uintptr_t localPlayer = 0x0;
constexpr uintptr_t entityList = 0x0;
constexpr uintptr_t viewMatrix = 0x0;
constexpr uintptr_t entityStride = 0x8;
constexpr uintptr_t health = 0x0;
constexpr uintptr_t team = 0x0;
constexpr uintptr_t headPos = 0x0;
constexpr int maxEntities = 64;
}

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };
struct Matrix4 { float m[16]; };

struct Entity {
    uintptr_t addr;
    int health;
    int team;
    Vec3 head;
};

class Memory {
public:
    Memory(const std::wstring& process, const std::wstring& module) {
        pid_ = findPid(process);
        if (!pid_) return;
        handle_ = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid_);
        base_ = findModule(module);
    }

    ~Memory() { if (handle_) CloseHandle(handle_); }
    Memory(const Memory&) = delete;
    Memory& operator=(const Memory&) = delete;

    bool valid() const { return handle_ && base_; }

    template <typename T>
    T read(uintptr_t addr) const {
        T value{};
        ReadProcessMemory(handle_, reinterpret_cast<LPCVOID>(addr), &value, sizeof(T), nullptr);
        return value;
    }

    Matrix4 viewMatrix() const { return read<Matrix4>(base_ + off::viewMatrix); }

    std::optional<Entity> localPlayer() const {
        uintptr_t addr = read<uintptr_t>(base_ + off::localPlayer);
        if (!addr) return std::nullopt;
        return readEntity(addr);
    }

    std::vector<Entity> entities(uintptr_t exclude) const {
        std::vector<Entity> out;
        uintptr_t list = base_ + off::entityList;
        for (int i = 0; i < off::maxEntities; ++i) {
            uintptr_t addr = read<uintptr_t>(list + i * off::entityStride);
            if (!addr || addr == exclude) continue;
            Entity e = readEntity(addr);
            if (e.health > 0) out.push_back(e);
        }
        return out;
    }

private:
    Entity readEntity(uintptr_t addr) const {
        return Entity{
            addr,
            read<int>(addr + off::health),
            read<int>(addr + off::team),
            read<Vec3>(addr + off::headPos),
        };
    }

    static DWORD findPid(const std::wstring& name) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return 0;
        PROCESSENTRY32W entry{ sizeof(entry) };
        DWORD pid = 0;
        for (BOOL ok = Process32FirstW(snap, &entry); ok; ok = Process32NextW(snap, &entry)) {
            if (_wcsicmp(entry.szExeFile, name.c_str()) == 0) { pid = entry.th32ProcessID; break; }
        }
        CloseHandle(snap);
        return pid;
    }

    uintptr_t findModule(const std::wstring& name) const {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_);
        if (snap == INVALID_HANDLE_VALUE) return 0;
        MODULEENTRY32W entry{ sizeof(entry) };
        uintptr_t base = 0;
        for (BOOL ok = Module32FirstW(snap, &entry); ok; ok = Module32NextW(snap, &entry)) {
            if (_wcsicmp(entry.szModule, name.c_str()) == 0) {
                base = reinterpret_cast<uintptr_t>(entry.modBaseAddr);
                break;
            }
        }
        CloseHandle(snap);
        return base;
    }

    DWORD pid_ = 0;
    HANDLE handle_ = nullptr;
    uintptr_t base_ = 0;
};

#include "mem.h"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <thread>

namespace cfg {
constexpr const wchar_t* process = L"game.exe";
constexpr const wchar_t* module = L"game.exe";
constexpr int hotkey = VK_XBUTTON2;
constexpr int exitKey = VK_END;
constexpr float fovRadius = 120.0f;
constexpr float easeDurationMs = 180.0f;
constexpr int tickMs = 5;
}

static std::optional<Vec2> worldToScreen(const Vec3& p, const Matrix4& vm, int w, int h) {
    const float* m = vm.m;
    float cw = m[12] * p.x + m[13] * p.y + m[14] * p.z + m[15];
    if (cw < 0.01f) return std::nullopt;
    float cx = m[0] * p.x + m[1] * p.y + m[2] * p.z + m[3];
    float cy = m[4] * p.x + m[5] * p.y + m[6] * p.z + m[7];
    float nx = cx / cw;
    float ny = cy / cw;
    return Vec2{ (w / 2.0f) * (1.0f + nx), (h / 2.0f) * (1.0f - ny) };
}

static float easeOutCubic(float t) {
    float u = 1.0f - std::clamp(t, 0.0f, 1.0f);
    return 1.0f - u * u * u;
}

static void moveMouse(int dx, int dy) {
    if (!dx && !dy) return;
    INPUT in{};
    in.type = INPUT_MOUSE;
    in.mi.dx = dx;
    in.mi.dy = dy;
    in.mi.dwFlags = MOUSEEVENTF_MOVE;
    SendInput(1, &in, sizeof(in));
}

static std::optional<Vec2> findTarget(const Memory& mem, int w, int h) {
    auto local = mem.localPlayer();
    if (!local) return std::nullopt;
    Matrix4 vm = mem.viewMatrix();
    Vec2 center{ w / 2.0f, h / 2.0f };
    std::optional<Vec2> best;
    float bestDist = cfg::fovRadius;
    for (const Entity& e : mem.entities(local->addr)) {
        if (e.team == local->team) continue;
        auto screen = worldToScreen(e.head, vm, w, h);
        if (!screen) continue;
        float dist = std::hypot(screen->x - center.x, screen->y - center.y);
        if (dist < bestDist) {
            bestDist = dist;
            best = Vec2{ screen->x - center.x, screen->y - center.y };
        }
    }
    return best;
}

int main() {
    Memory mem(cfg::process, cfg::module);
    if (!mem.valid()) {
        std::fprintf(stderr, "process or module not found\n");
        return 1;
    }
    int w = GetSystemMetrics(SM_CXSCREEN);
    int h = GetSystemMetrics(SM_CYSCREEN);
    float progress = 0.0f;
    float carryX = 0.0f, carryY = 0.0f;

    while (!(GetAsyncKeyState(cfg::exitKey) & 0x8000)) {
        if (!(GetAsyncKeyState(cfg::hotkey) & 0x8000)) {
            progress = 0.0f;
            carryX = carryY = 0.0f;
            std::this_thread::sleep_for(std::chrono::milliseconds(cfg::tickMs));
            continue;
        }
        auto delta = findTarget(mem, w, h);
        if (!delta) {
            progress = 0.0f;
        } else {
            float next = std::min(progress + cfg::tickMs / cfg::easeDurationMs, 1.0f);
            float done = easeOutCubic(progress);
            float frac = done >= 1.0f ? 1.0f : (easeOutCubic(next) - done) / (1.0f - done);
            float mx = delta->x * frac + carryX;
            float my = delta->y * frac + carryY;
            int ix = static_cast<int>(mx);
            int iy = static_cast<int>(my);
            carryX = mx - ix;
            carryY = my - iy;
            moveMouse(ix, iy);
            progress = next;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(cfg::tickMs));
    }
    return 0;
}
